import http.server, socketserver, threading, time

def log(*a):
    print("[sinkhole]", *a, flush=True)

class H(http.server.BaseHTTPRequestHandler):
    def _handle(self):
        log("HTTP", self.command, self.path, "from", self.client_address[0],
            "ua=", self.headers.get("User-Agent"))
        try:
            n = int(self.headers.get("Content-Length", "0") or "0")
            if n:
                log("  body:", self.rfile.read(min(n, 2048))[:512])
        except Exception:
            pass
        body = b"mlscan-sinkhole"
        self.send_response(200)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)
    do_GET = do_POST = do_PUT = do_DELETE = do_HEAD = _handle
    def log_message(self, *a):
        pass

class TCP(socketserver.BaseRequestHandler):
    def handle(self):
        log("TCP connect on", self.server.server_address[1], "from", self.client_address[0])
        try:
            data = self.request.recv(256)
            if data:
                log("  data:", data[:160])
        except Exception:
            pass

def serve_http():
    http.server.ThreadingHTTPServer(("0.0.0.0", 8080), H).serve_forever()

def serve_tcp(port):
    socketserver.ThreadingTCPServer(("0.0.0.0", port), TCP).serve_forever()

def main():
    threading.Thread(target=serve_http, daemon=True).start()
    for p in (4444, 9001, 1337):
        threading.Thread(target=serve_tcp, args=(p,), daemon=True).start()
    log("sinkhole up: http 8080, tcp 4444/9001/1337")
    while True:
        time.sleep(3600)

main()
